// ===== 书耽 m.shubl.com 正文解密：base64 + MD5(EVP_BytesToKey) + AES-256-CBC =====
// 纯 JS 实现，byte 用 latin1 字符串表示

var B64 = (function () {
  var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  var lookup = {};
  for (var i = 0; i < 64; i++) lookup[chars.charAt(i)] = i;
  function encode(s) {
    var out = '', i = 0, n = s.length;
    for (; i + 2 < n; i += 3) {
      var c1 = s.charCodeAt(i), c2 = s.charCodeAt(i + 1), c3 = s.charCodeAt(i + 2);
      out += chars.charAt(c1 >> 2) + chars.charAt(((c1 & 3) << 4) | (c2 >> 4)) +
             chars.charAt(((c2 & 15) << 2) | (c3 >> 6)) + chars.charAt(c3 & 63);
    }
    var rem = n - i;
    if (rem === 1) { var a = s.charCodeAt(i); out += chars.charAt(a >> 2) + chars.charAt((a & 3) << 4) + '=='; }
    else if (rem === 2) { var b = s.charCodeAt(i), c = s.charCodeAt(i + 1); out += chars.charAt(b >> 2) + chars.charAt(((b & 3) << 4) | (c >> 4)) + chars.charAt((c & 15) << 2) + '='; }
    return out;
  }
  function decode(str) {
    str = str.replace(/[^A-Za-z0-9+/]/g, '');
    var out = '', buf = 0, bits = 0;
    for (var i = 0; i < str.length; i++) {
      buf = (buf << 6) | lookup[str.charAt(i)];
      bits += 6;
      if (bits >= 8) { bits -= 8; out += String.fromCharCode((buf >> bits) & 255); }
    }
    return out;
  }
  return { encode: encode, decode: decode };
})();

function utf8Decode(byteStr) {
  var out = '', i = 0, n = byteStr.length;
  while (i < n) {
    var c = byteStr.charCodeAt(i++);
    if (c < 0x80) out += String.fromCharCode(c);
    else if (c < 0xE0) out += String.fromCharCode(((c & 0x1F) << 6) | (byteStr.charCodeAt(i++) & 0x3F));
    else if (c < 0xF0) out += String.fromCharCode(((c & 0x0F) << 12) | ((byteStr.charCodeAt(i++) & 0x3F) << 6) | (byteStr.charCodeAt(i++) & 0x3F));
    else {
      var cp = ((c & 0x07) << 18) | ((byteStr.charCodeAt(i++) & 0x3F) << 12) | ((byteStr.charCodeAt(i++) & 0x3F) << 6) | (byteStr.charCodeAt(i++) & 0x3F);
      cp -= 0x10000; out += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
    }
  }
  return out;
}

// ---- MD5 (input latin1 byte string -> 16-byte latin1 string) ----
var md5 = (function () {
  var K = [];
  for (var i = 0; i < 64; i++) K[i] = (Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296)) | 0;
  var S = [7,12,17,22,7,12,17,22,7,12,17,22,7,12,17,22,
           5,9,14,20,5,9,14,20,5,9,14,20,5,9,14,20,
           4,11,16,23,4,11,16,23,4,11,16,23,4,11,16,23,
           6,10,15,21,6,10,15,21,6,10,15,21,6,10,15,21];
  function rol(x, c) { return (x << c) | (x >>> (32 - c)); }
  return function (str) {
    var bytes = [];
    for (var i = 0; i < str.length; i++) bytes.push(str.charCodeAt(i) & 0xff);
    var n = bytes.length, bitLen = n * 8;
    bytes.push(0x80);
    while (bytes.length % 64 !== 56) bytes.push(0);
    for (var i = 0; i < 8; i++) bytes.push((Math.floor(bitLen / Math.pow(2, 8 * i))) & 0xff);
    var a0 = 0x67452301, b0 = 0xefcdab89, c0 = 0x98badcfe, d0 = 0x10325476;
    for (var off = 0; off < bytes.length; off += 64) {
      var M = [];
      for (var j = 0; j < 16; j++) M[j] = bytes[off + 4 * j] | (bytes[off + 4 * j + 1] << 8) | (bytes[off + 4 * j + 2] << 16) | (bytes[off + 4 * j + 3] << 24);
      var A = a0, B = b0, C = c0, D = d0;
      for (var i2 = 0; i2 < 64; i2++) {
        var F, g;
        if (i2 < 16) { F = (B & C) | (~B & D); g = i2; }
        else if (i2 < 32) { F = (D & B) | (~D & C); g = (5 * i2 + 1) % 16; }
        else if (i2 < 48) { F = B ^ C ^ D; g = (3 * i2 + 5) % 16; }
        else { F = C ^ (B | ~D); g = (7 * i2) % 16; }
        F = (F + A + K[i2] + M[g]) | 0;
        A = D; D = C; C = B;
        B = (B + rol(F, S[i2])) | 0;
      }
      a0 = (a0 + A) | 0; b0 = (b0 + B) | 0; c0 = (c0 + C) | 0; d0 = (d0 + D) | 0;
    }
    var words = [a0, b0, c0, d0], s = '';
    for (var w = 0; w < 4; w++) for (var b = 0; b < 4; b++) s += String.fromCharCode((words[w] >>> (8 * b)) & 0xff);
    return s;
  };
})();

// ---- AES ----
var AES = (function () {
  function mul(a, b) { var p = 0; for (var i = 0; i < 8; i++) { if (b & 1) p ^= a; var hi = a & 0x80; a = (a << 1) & 0xff; if (hi) a ^= 0x1b; b >>= 1; } return p & 0xff; }
  function rot(x, n) { return ((x << n) | (x >>> (8 - n))) & 0xff; }
  var SBOX = new Array(256), RSBOX = new Array(256);
  (function () {
    for (var i = 0; i < 256; i++) {
      var inv;
      if (i === 0) inv = 0;
      else { var r = 1, x = i, e = 254; while (e > 0) { if (e & 1) r = mul(r, x); x = mul(x, x); e >>= 1; } inv = r; }
      var s = (inv ^ rot(inv, 1) ^ rot(inv, 2) ^ rot(inv, 3) ^ rot(inv, 4) ^ 0x63) & 0xff;
      SBOX[i] = s; RSBOX[s] = i;
    }
  })();
  var RCON = [0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36,0x6c,0xd8,0xab,0x4d];
  function expandKey(key) {
    var Nk = key.length / 4, Nr = Nk + 6, w = new Array(4 * (Nr + 1));
    for (var i = 0; i < Nk; i++) w[i] = ((key[4*i] << 24) | (key[4*i+1] << 16) | (key[4*i+2] << 8) | key[4*i+3]) >>> 0;
    for (var i = Nk; i < 4 * (Nr + 1); i++) {
      var t = w[i-1];
      if (i % Nk === 0) {
        t = ((t << 8) | (t >>> 24)) >>> 0;
        t = ((SBOX[(t >>> 24) & 0xff] << 24) | (SBOX[(t >>> 16) & 0xff] << 16) | (SBOX[(t >>> 8) & 0xff] << 8) | SBOX[t & 0xff]) >>> 0;
        t = (t ^ (RCON[(i / Nk) - 1] << 24)) >>> 0;
      } else if (Nk > 6 && i % Nk === 4) {
        t = ((SBOX[(t >>> 24) & 0xff] << 24) | (SBOX[(t >>> 16) & 0xff] << 16) | (SBOX[(t >>> 8) & 0xff] << 8) | SBOX[t & 0xff]) >>> 0;
      }
      w[i] = (w[i - Nk] ^ t) >>> 0;
    }
    return { w: w, Nr: Nr };
  }
  function addRoundKey(st, w, round) {
    for (var c = 0; c < 4; c++) { var word = w[round * 4 + c]; st[4*c] ^= (word >>> 24) & 0xff; st[4*c+1] ^= (word >>> 16) & 0xff; st[4*c+2] ^= (word >>> 8) & 0xff; st[4*c+3] ^= word & 0xff; }
  }
  function invShiftRows(s) {
    var t = s[13]; s[13] = s[9]; s[9] = s[5]; s[5] = s[1]; s[1] = t;
    t = s[2]; s[2] = s[10]; s[10] = t; t = s[6]; s[6] = s[14]; s[14] = t;
    t = s[3]; s[3] = s[7]; s[7] = s[11]; s[11] = s[15]; s[15] = t;
  }
  function invMixColumns(st) {
    for (var c = 0; c < 4; c++) {
      var a0 = st[4*c], a1 = st[4*c+1], a2 = st[4*c+2], a3 = st[4*c+3];
      st[4*c]   = mul(a0,14) ^ mul(a1,11) ^ mul(a2,13) ^ mul(a3,9);
      st[4*c+1] = mul(a0,9)  ^ mul(a1,14) ^ mul(a2,11) ^ mul(a3,13);
      st[4*c+2] = mul(a0,13) ^ mul(a1,9)  ^ mul(a2,14) ^ mul(a3,11);
      st[4*c+3] = mul(a0,11) ^ mul(a1,13) ^ mul(a2,9)  ^ mul(a3,14);
    }
  }
  function decryptBlock(block, exp) {
    var st = block.slice(0);
    addRoundKey(st, exp.w, exp.Nr);
    for (var round = exp.Nr - 1; round >= 1; round--) {
      invShiftRows(st);
      for (var i = 0; i < 16; i++) st[i] = RSBOX[st[i]];
      addRoundKey(st, exp.w, round);
      invMixColumns(st);
    }
    invShiftRows(st);
    for (var i = 0; i < 16; i++) st[i] = RSBOX[st[i]];
    addRoundKey(st, exp.w, 0);
    return st;
  }
  function cbcDecrypt(ctStr, keyStr, ivStr) {
    var key = []; for (var i = 0; i < keyStr.length; i++) key.push(keyStr.charCodeAt(i) & 0xff);
    var iv = []; for (var i = 0; i < ivStr.length; i++) iv.push(ivStr.charCodeAt(i) & 0xff);
    var exp = expandKey(key);
    var out = '', prev = iv, i = 0;
    for (; i + 16 <= ctStr.length; i += 16) {
      var blk = []; for (var j = 0; j < 16; j++) blk.push(ctStr.charCodeAt(i + j) & 0xff);
      var dec = decryptBlock(blk, exp);
      for (var j = 0; j < 16; j++) out += String.fromCharCode(dec[j] ^ prev[j]);
      prev = blk;
    }
    return out;
  }
  return { cbcDecrypt: cbcDecrypt };
})();

function evpBytesToKey(passStr, saltStr, klen, ivlen) {
  var d = '', prev = '', i = 0;
  while (d.length < klen + ivlen) { prev = md5(prev + passStr + saltStr); d += prev; i++; }
  return { key: d.substring(0, klen), iv: d.substring(klen, klen + ivlen) };
}

function unpadBytes(s) {
  if (!s) return s;
  var pad = s.charCodeAt(s.length - 1);
  if (pad >= 1 && pad <= 16 && pad <= s.length) {
    var ok = true;
    for (var i = 0; i < pad; i++) { if (s.charCodeAt(s.length - 1 - i) !== pad) { ok = false; break; } }
    if (ok) return s.substring(0, s.length - pad);
  }
  return s;
}

function myDecrypt(content, keys, accessKey) {
  var k = [keys[accessKey.charCodeAt(accessKey.length - 1) % keys.length],
           keys[accessKey.charCodeAt(0) % keys.length]];
  var n = content;
  for (var i = 0; i < k.length; i++) {
    var nb = B64.decode(n);
    var iv = nb.substring(0, 16);
    var data = nb.substring(16);
    var pt;
    if (data.substring(0, 8) === 'Salted__') {
      var salt = data.substring(8, 16);
      var ct = data.substring(16);
      var ki = evpBytesToKey(B64.decode(k[i]), salt, 32, 16);
      pt = AES.cbcDecrypt(ct, ki.key, ki.iv);
    } else {
      pt = AES.cbcDecrypt(data, B64.decode(k[i]), iv);
    }
    n = (i < k.length - 1) ? pt : unpadBytes(utf8Decode(pt));
  }
  return n;
}

if (typeof module !== 'undefined') { module.exports = { myDecrypt: myDecrypt, B64: B64, md5: md5 }; }

function hwDecrypt(b64) {
  if (!b64) return '';
  var pt = AES.cbcDecrypt(B64.decode(b64), '2018122911430000', '048fe2a99140c0e6');
  pt = pt.replace(/\x00+$/, '');
  return decodeURIComponent(utf8Decode(pt));
}

function hwCover(id) {
  var s = String(id);
  return "https://cnimg.hanwujinian.net/files/article/image/" + s.substring(0, 3) + "/" + s + "/" + s + "s.jpg";
}

function hwFixCover(u, id) {
  var fb = hwCover(id);
  if (!u) return fb;
  u = String(u).replace(/^http:/, "https:");
  if (u.indexOf("nocover") > -1) return fb;
  if (!/\.(jpg|jpeg|png|webp|gif)(\?.*)?$/i.test(u)) { u = u + "s.jpg"; }
  return u;
}
